import graphene
from graphql import GraphQLError
from .models import PatientMedicalChart

class UpdateMedicalChartMutation(graphene.Mutation):
    class Arguments:
        chart_id = graphene.Int(required=True)
        notes = graphene.String(required=True)

    success = graphene.Boolean()

    def mutate(self, info, chart_id, notes):
        user = info.context.user
        if not user.is_authenticated:
            raise GraphQLError('Login required')

        try:
            # Ensure the doctor is specifically assigned to the patient or authorized department
            chart = PatientMedicalChart.objects.get(id=chart_id, assigned_doctors=user)
            chart.clinical_notes = notes
            chart.save(update_fields=['clinical_notes'])
            return UpdateMedicalChartMutation(success=True)
        except PatientMedicalChart.DoesNotExist:
            raise GraphQLError('Chart not found or doctor not assigned to this patient')
